import{z as p,x as A,o as t,c as d,q as r,j as o,D as e,d as l,s,S as n,b as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"面板级封装光刻","description":"","frontmatter":{"title":"面板级封装光刻","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/panel-level-litho.md","filePath":"litho/panel-level-litho.md","lastUpdated":1791413859000}'),B={name:"litho/panel-level-litho.md"};function h(m,a,f,D,c,P){const E=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="面板级封装光刻" tabindex="-1">面板级封装光刻 <a class="header-anchor" href="#面板级封装光刻" aria-label="Permalink to &quot;面板级封装光刻&quot;">​</a></h1><div class="epigraph"><p>矩形大板比 300 mm 圆片便宜摊面积，但膨胀、翘曲和套刻在几十厘米上积分，光刻从扫描机问题变成基板问题。</p><footer>—— 对照 panel-level packaging（FOPLP）光刻与畸变的公开讨论</footer></div><p><a href="/litho/laser-direct-write-packaging">上一课</a>选了封装工具族。缺口是基板从圆变方、变大。本课钉面板级封装光刻。显示面板更极端的场，留给<a href="/litho/display-litho">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FOPLP 一类用大面板做 fan-out，面积经济好。光刻挑战：面板膨胀与过程热循环、局部翘曲、真空或机械夹持均匀性、拼接多场、套刻到重建芯片的真实位置（die shift）。步进器或扫描投影要有大行程与畸变校正，不是更高 NA。</p><p><span class="marginnote">FOPLP（扇出型面板级封装）可以这样理解：把许多小芯片摆在一块大矩形板的空位里，再用光刻在板上「画」出把它们连出去的再布线（RDL）。板比圆晶圆面积利用率高、摊薄成本，但越大越难管翘曲与套刻。</span></p><p>缺口是<strong>大尺寸畸变</strong>，不是 k1。把面板当「大晶圆」，夹持与热模型都错。</p><h3 id="die-shift" tabindex="-1">Die shift <a class="header-anchor" href="#die-shift" aria-label="Permalink to &quot;Die shift&quot;">​</a></h3><p>贴片位置误差是封装套刻的一部分，光刻只能补测量到的部分。混合键合课会在更严的 nm 上再遇对准；面板级通常更松，但面积放大后仍可超差。</p><p><span class="marginnote">面板材料（玻璃、有机）的 CTE 与硅不同，多层套刻随温度定义走。计量要声明温度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计量：全板栅格、温度补偿。曝光：分步拼接 + 畸变图。工艺：低温、对称结构减翘曲。与产能：大板一张等于许多圆片面积，但良率按板，一块报废损失大。</p>',12)),(t(),o(n,null,{default:e(()=>[s(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E9%9D%A2%E6%9D%BF%E8%A3%85%E8%BD%BD%E4%B8%8E%E4%BD%8E%E6%B8%A9%E5%A4%B9%E6%8C%81%22%5D%20--%3E%20MEAS%5B%22%E5%85%A8%E6%9D%BF%E6%A0%85%E6%A0%BC%E6%B5%8B%E9%87%8F(%E5%90%AB%E6%B8%A9%E5%BA%A6%E8%A1%A5%E5%81%BF)%22%5D%0A%20%20MEAS%20--%3E%20MAP%5B%22%E7%95%B8%E5%8F%98%E5%9B%BE%20%2B%20die%20shift%20%E8%A1%A8%22%5D%0A%20%20MAP%20--%3E%20PLAN%5B%22%E5%88%86%E5%9C%BA%E6%8B%BC%E6%8E%A5%E4%B8%8E%E6%9B%9D%E5%85%89%E8%AE%A1%E5%88%92%22%5D%0A%20%20PLAN%20--%3E%20EXP%5B%22%E9%80%90%E5%9C%BA%E6%9B%9D%E5%85%89%22%5D%0A%20%20EXP%20--%3E%20CHK%5B%22%E5%A5%97%E5%88%BB%E6%8A%BD%E6%A3%80%22%5D%0A%20%20CHK%20--%3E%20MEAS%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[l("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"热位移 ∝ CTE × ΔT × 长度。长度从 300 mm 到 500–600 mm 量级，同样 ΔT 的位移按比例涨。光学畸变校正是多项式，板的真实变形可能含局部贴片团，需栅格而不是低阶。",-1)),(t(),o(n,null,{default:e(()=>[s(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20PANEL%5B%22%E5%A4%A7%E9%9D%A2%E6%9D%BF%22%5D%20--%3E%20STRAIN%5B%22CTE%20%C3%97%20%E9%95%BF%E5%BA%A6%22%5D%0A%20%20SHIFT%5B%22die%20shift%22%5D%20--%3E%20OL%5B%22%E5%A5%97%E5%88%BB%E9%A2%84%E7%AE%97%22%5D%0A%20%20STRAIN%20--%3E%20OL%0A%20%20OL%20--%3E%20CORR%5B%22%E7%95%B8%E5%8F%98%E5%9B%BE%20%2F%20%E6%8B%BC%E6%8E%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">代个数字：设面板与硅的热失配约每摄氏度 10 ppm，ΔT=20 °C 时 300 mm 圆片伸缩约 60 µm；换成 600 mm 面板同样条件就是 120 µm——长度翻倍、位移翻倍，套刻预算却不会跟着翻倍。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不点名某代面板尺寸当唯一标准。不把面板良率写成逻辑晶圆良率模型直接套用——缺陷经济学不同。</p><p><span class="marginnote">常见误区：把面板当「大一号的晶圆」，直接套用圆片光刻的热与夹持模型。矩形板的边缘翘曲、贴片团簇这类局部变形不是低阶多项式能拟合的，校正必须依赖逐板实测栅格，否则中心场合格、边缘场成片超差。</span></p><p>后课默认：大板套刻是基板物理学；下一课显示把板做得更大、CD 更松。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>面板级光刻的墙是膨胀、翘曲、die shift，不是 NA。</li><li>应变随长度放大；校正需要全板栅格。</li><li>面积经济与整板报废风险同时存在。</li><li>出处：FOPLP / panel-level 光刻公开讨论。</li></ul>',7))])}const T=p(B,[["render",h]]);export{_ as __pageData,T as default};
